import type { ConfigContext, ExpoConfig } from "expo/config";

/**
 * Driver app configuration (docs/08 §8, Android only: docs/01 Q8).
 *
 * Continuous Native Generation: `android/` is generated by `expo prebuild` from
 * this file and is never committed, so native configuration has one source.
 *
 * Background location (docs/technology-decisions.md §5.3) needs, on Android:
 * ACCESS_BACKGROUND_LOCATION, a foreground service of type `location`
 * (FOREGROUND_SERVICE + FOREGROUND_SERVICE_LOCATION), and a visible
 * notification while tracking. The expo-location plugin adds all of them from
 * the two flags below. The permission strings are what Play review and the
 * driver read, so they say exactly when and why.
 */
/** Set per EAS environment (eas.json); the emulator's host loopback otherwise. */
const configuredApiUrl: unknown = process.env["EXPO_PUBLIC_API_URL"];
const apiUrl =
  typeof configuredApiUrl === "string" && configuredApiUrl !== ""
    ? configuredApiUrl
    : "http://10.0.2.2:3000";

export default ({ config }: ConfigContext): ExpoConfig => ({
  ...config,
  name: "Delivery Driver",
  slug: "delivery-driver",
  // The Expo account and project EAS builds under (created by `eas init`,
  // 2026-10-19). Identifiers, not credentials: builds still need a login or an
  // EXPO_TOKEN, which never lives in the repo.
  owner: "salemwachwachaaa",
  scheme: "deliverydriver",
  version: "0.1.0",
  orientation: "portrait",
  platforms: ["android"],
  android: {
    package: "tn.delivery.driver",
    versionCode: 1,
    // Tokens and the database key live in the Keystore; nothing to restore.
    allowBackup: false,
    // The plugins add exactly the location and foreground-service permissions.
    // REQUEST_IGNORE_BATTERY_OPTIMIZATIONS is deliberately NOT requested: Play
    // restricts it. The app opens the battery-optimisation settings list
    // instead (no permission needed) and the driver exempts it there.
    permissions: [],
    // Defaults from Expo's template the app never needs. Every permission is a
    // question in Play review and a reason for a driver to distrust the app.
    blockedPermissions: [
      "android.permission.RECORD_AUDIO",
      "android.permission.SYSTEM_ALERT_WINDOW",
      "android.permission.READ_EXTERNAL_STORAGE",
      "android.permission.WRITE_EXTERNAL_STORAGE",
    ],
  },
  plugins: [
    "expo-router",
    "expo-secure-store",
    [
      "expo-localization",
      // Arabic is right-to-left from the first screen (docs/01 §7.3).
      { supportsRTL: true },
    ],
    [
      // Parcel labels and proof-of-delivery photos. No microphone: the app
      // never records video, so RECORD_AUDIO is not even declared.
      "expo-camera",
      {
        cameraPermission: "The camera scans parcel labels and photographs proof of delivery.",
        recordAudioAndroid: false,
        barcodeScannerEnabled: true,
      },
    ],
    [
      "expo-location",
      {
        isAndroidBackgroundLocationEnabled: true,
        isAndroidForegroundServiceEnabled: true,
        locationAlwaysAndWhenInUsePermission:
          "Your location is shared with dispatch only while your shift is open, so your route and arrivals can be tracked.",
      },
    ],
  ],
  // Over-the-air updates are OFF until EAS Update and its signing are set up:
  // an unsigned update channel would be a way to ship code to every driver.
  updates: { enabled: false },
  experiments: {
    typedRoutes: true,
  },
  extra: {
    // Read by src/config.ts; validated there, never used raw.
    apiUrl,
    eas: { projectId: "e1d3b850-b54c-4cd3-8dbf-c1d20451718b" },
  },
});
